"""Regression checks for the SDK contract alignment (without provider requests)."""

import json
from typing import Any

import gigachat.models as gm
import httpx
import pytest
from gigachat.context import session_id_cvar
from gigachat.settings import Settings
from langchain_core.messages import AIMessage, AIMessageChunk, HumanMessage

from langchain_gigachat import GigaChat
from langchain_gigachat.chat_models.gigachat import (
    _convert_delta_to_message_chunk,
    _convert_dict_to_message,
    _convert_message_to_dict,
)
from langchain_gigachat.embeddings import GigaChatEmbeddings


def _response() -> dict[str, Any]:
    return {
        "choices": [
            {
                "message": {"role": "assistant", "content": "ok"},
                "index": 0,
                "finish_reason": "stop",
            }
        ],
        "created": 1,
        "model": "test-model",
        "object": "chat.completion",
        "usage": {
            "prompt_tokens": 14,
            "precached_prompt_tokens": 2430,
            "completion_tokens": 2,
            "total_tokens": 16,
        },
    }


@pytest.mark.parametrize("primary", [False, True])
@pytest.mark.parametrize("context_id", [None, "context-session"])
async def test_session_header_reaches_sdk_sync_and_async(
    monkeypatch: pytest.MonkeyPatch,
    primary: bool,
    context_id: str | None,
) -> None:
    if "session_id" not in Settings.model_fields:
        pytest.skip("SDK session_id support requires the aligned SDK")
    seen: list[httpx.Request] = []
    body = (
        {"messages": [{"role": "assistant", "content": "ok"}]}
        if primary
        else _response()
    )

    def send(
        client: httpx.Client, request: httpx.Request, **kwargs: Any
    ) -> httpx.Response:
        seen.append(request)
        return httpx.Response(200, json=body, request=request)

    async def asend(
        client: httpx.AsyncClient, request: httpx.Request, **kwargs: Any
    ) -> httpx.Response:
        seen.append(request)
        return httpx.Response(200, json=body, request=request)

    monkeypatch.setattr(httpx.Client, "send", send)
    monkeypatch.setattr(httpx.AsyncClient, "send", asend)
    llm = GigaChat(
        model="test-model",
        access_token="test-token",
        session_id="client-session",
        use_api_v2=primary,
    )
    token = [REDACTED]
    try:
        assert llm.invoke("hello").content == "ok"
        assert (await llm.ainvoke("hello")).content == "ok"
        assert session_id_cvar.get() == context_id
    finally:
        session_id_cvar.reset(token)
    assert len(seen) == 2
    assert all(
        request.headers["X-Session-ID"] == (context_id or "client-session")
        for request in seen
    )
    route = "/v2/chat/completions" if primary else "/v1/chat/completions"
    assert all(request.url.path == route for request in seen)


@pytest.mark.parametrize("model_class", [GigaChat, GigaChatEmbeddings])
def test_session_id_not_silently_ignored_by_older_sdk(model_class: Any) -> None:
    model = model_class(session_id="session")
    if "session_id" in Settings.model_fields:
        assert model._get_client_init_kwargs()["session_id"] == "session"
    else:
        with pytest.raises(ValueError, match="session_id requires"):
            model._get_client_init_kwargs()


def test_legacy_reasoning_budget_and_invocation_override() -> None:
    llm = GigaChat(reasoning_effort="low", reasoning_max_tokens=128)
    payload = llm._build_payload(
        [HumanMessage(content="hello")],
        reasoning_effort="high",
        reasoning_max_tokens=64,
    )
    from gigachat.api.chat import _build_request_json

    body = _build_request_json(payload)
    assert body["reasoning_effort"] == "high"
    assert body["reasoning_max_tokens"] == 64
    assert "additional_fields" not in body


def test_legacy_assistant_id_is_supported_by_aligned_sdk() -> None:
    llm = GigaChat()
    llm._validate_legacy_kwargs({"assistant_id": "assistant"})
    if "assistant_id" not in gm.Chat.model_fields:
        with pytest.raises(ValueError, match="updated GigaChat SDK"):
            llm._build_payload(
                [HumanMessage(content="hello")], assistant_id="assistant"
            )
    else:
        payload = llm._build_payload(
            [HumanMessage(content="hello")], assistant_id="assistant"
        )
        assert payload.model_dump()["assistant_id"] == "assistant"


def test_legacy_usage_includes_cached_input_but_keeps_raw_counts() -> None:
    result = GigaChat()._create_chat_result(
        gm.ChatCompletion.model_validate(_response())
    )
    message = result.generations[0].message
    assert isinstance(message, AIMessage)
    assert message.usage_metadata == {
        "input_tokens": 2444,
        "output_tokens": 2,
        "total_tokens": 2446,
        "input_token_details": {"cache_read": 2430},
    }
    assert result.llm_output is not None
    assert result.llm_output["token_usage"]["prompt_tokens"] == 14
    assert result.llm_output["token_usage"]["total_tokens"] == 16


@pytest.mark.skipif(
    "id_" not in gm.FunctionCall.model_fields,
    reason="SDK function-call IDs require aligned SDK",
)
def test_legacy_function_id_roundtrip_and_stream() -> None:
    raw = {
        "role": "assistant",
        "content": "",
        "functions_state_id": "state",
        "function_call": {"id": "call-1", "name": "lookup", "arguments": {"x": 1}},
    }
    message = _convert_dict_to_message(gm.Messages.model_validate(raw))
    assert isinstance(message, AIMessage)
    assert message.tool_calls[0]["id"] == "call-1"
    assert message.additional_kwargs["functions_state_id"] == "state"
    assert (
        _convert_message_to_dict(message).model_dump(by_alias=True)["function_call"][
            "id"
        ]
        == "call-1"
    )
    chunk = _convert_delta_to_message_chunk(raw, AIMessageChunk)
    assert isinstance(chunk, AIMessageChunk)
    assert chunk.tool_calls[0]["id"] == "call-1"


@pytest.mark.skipif(
    "additional_data" not in gm.ChatCompletion.model_fields,
    reason="SDK metadata requires aligned SDK",
)
def test_legacy_response_and_stream_preserve_contract_metadata() -> None:
    payload = _response()
    metadata = {
        "thread_id": "thread",
        "message_id": "message",
        "additional_data": {"sources": [{"title": "Example"}]},
        "error_details": {"http_status": 200},
    }
    payload.update(metadata)
    payload["choices"][0]["message"].update(
        {"inline_data": {"sources": []}, "logprobs": [{"token": "ok", "logprob": -0.1}]}
    )
    result = GigaChat()._create_chat_result(gm.ChatCompletion.model_validate(payload))
    message = result.generations[0].message
    for key, value in metadata.items():
        assert message.response_metadata[key] == value
    assert message.additional_kwargs["inline_data"] == {"sources": []}
    assert message.additional_kwargs["logprobs"][0]["token"] == "ok"
    stream = {**metadata, "choices": [{"delta": {"content": "ok"}}]}
    pending: dict[str, Any] = {}
    llm = GigaChat()
    _, first, _ = llm._build_stream_chunk(stream, True, pending)
    _, second, _ = llm._build_stream_chunk(stream, False, pending)
    assert first == {"x_headers": {}}
    assert second == {}
    assert pending == metadata


@pytest.mark.skipif(
    "additional_data" not in gm.ChatCompletionChunk.model_fields,
    reason="SDK metadata requires aligned SDK",
)
@pytest.mark.parametrize("asynchronous", [False, True])
async def test_legacy_metadata_snapshots_survive_sdk_http_stream(
    monkeypatch: pytest.MonkeyPatch, asynchronous: bool
) -> None:
    common = {
        "created": 1,
        "model": "test-model",
        "object": "chat.completion.chunk",
        "thread_id": "thread",
        "message_id": "message",
    }
    draft = {"sources": [{"index": 0, "url": "https://example.com", "title": "Draft"}]}
    final = {"sources": [{"index": 0, "url": "https://example.com", "title": "Final"}]}
    events = [
        {
            **common,
            "choices": [{"delta": {"content": "ok"}, "index": 0}],
            "additional_data": draft,
            "error_details": {"message": "Pending"},
        },
        {
            **common,
            "choices": [{"delta": {}, "index": 0, "finish_reason": "stop"}],
            "additional_data": draft,
        },
        {
            **common,
            "choices": [],
            "additional_data": final,
            "error_details": {"message": "Complete"},
            "usage": {"prompt_tokens": 5, "completion_tokens": 2, "total_tokens": 7},
        },
    ]
    body = "".join(f"data: {json.dumps(event)}\n\n" for event in events)
    body += "data: [DONE]\n\n"
    seen: list[httpx.Request] = []

    def send(
        client: httpx.Client | httpx.AsyncClient, request: httpx.Request, **kwargs: Any
    ) -> httpx.Response:
        seen.append(request)
        return httpx.Response(
            200,
            text=body,
            headers={"content-type": "text/event-stream", "x-request-id": "request"},
            request=request,
        )

    async def asend(
        client: httpx.AsyncClient, request: httpx.Request, **kwargs: Any
    ) -> httpx.Response:
        return send(client, request, **kwargs)

    monkeypatch.setattr(httpx.Client, "send", send)
    monkeypatch.setattr(httpx.AsyncClient, "send", asend)
    llm = GigaChat(model="test-model", access_token="test-token")
    chunks = (
        [chunk async for chunk in llm.astream("hello")]
        if asynchronous
        else list(llm.stream("hello"))
    )
    aggregate = chunks[0]
    for chunk in chunks[1:]:
        aggregate += chunk
    assert aggregate.content == "ok"
    assert aggregate.id == chunks[-1].id == "request"
    assert aggregate.response_metadata["additional_data"] == final
    assert aggregate.response_metadata["error_details"] == {"message": "Complete"}
    assert aggregate.response_metadata["thread_id"] == "thread"
    assert aggregate.response_metadata["message_id"] == "message"
    assert aggregate.usage_metadata == {
        "input_tokens": 5,
        "output_tokens": 2,
        "total_tokens": 7,
        "input_token_details": {"cache_read": 0},
    }
    assert len(seen) == 1
    assert seen[0].url.path == "/v1/chat/completions"

"""Tests for _convert_delta_to_message_chunk and _build_stream_chunk."""

import json
from typing import Any, AsyncIterator, Dict, Iterator

import pytest
from langchain_core.callbacks import BaseCallbackHandler
from langchain_core.messages import (
    AIMessageChunk,
    ChatMessageChunk,
    FunctionMessageChunk,
    HumanMessageChunk,
    SystemMessageChunk,
)
from pytest_mock import MockerFixture

from langchain_gigachat.chat_models.gigachat import (
    GigaChat,
    _convert_delta_to_message_chunk,
)

# ---------------------------------------------------------------------------
# _convert_delta_to_message_chunk
# ---------------------------------------------------------------------------


def test_delta_user_role() -> None:
    chunk = _convert_delta_to_message_chunk(
        {"role": "user", "content": "hello"}, AIMessageChunk
    )
    assert isinstance(chunk, HumanMessageChunk)
    assert chunk.content == "hello"


def test_delta_system_role() -> None:
    chunk = _convert_delta_to_message_chunk(
        {"role": "system", "content": "sys"}, SystemMessageChunk
    )
    assert isinstance(chunk, SystemMessageChunk)


def test_delta_function_role() -> None:
    chunk = _convert_delta_to_message_chunk(
        {"role": "function", "content": '{"r":1}', "name": "calc"},
        FunctionMessageChunk,
    )
    assert isinstance(chunk, FunctionMessageChunk)
    assert chunk.name == "calc"


def test_delta_assistant_role() -> None:
    chunk = _convert_delta_to_message_chunk(
        {"role": "assistant", "content": "hi"}, AIMessageChunk
    )
    assert isinstance(chunk, AIMessageChunk)
    assert chunk.content == "hi"


def test_delta_assistant_default_class_takes_priority() -> None:
    """When default_class is AIMessageChunk, assistant branch wins over system role."""
    chunk = _convert_delta_to_message_chunk(
        {"role": "system", "content": "sys"}, AIMessageChunk
    )
    assert isinstance(chunk, AIMessageChunk)


def test_delta_default_class_fallback() -> None:
    chunk = _convert_delta_to_message_chunk({"content": "text"}, HumanMessageChunk)
    assert isinstance(chunk, HumanMessageChunk)


def test_delta_chat_message_chunk_unknown_role() -> None:
    chunk = _convert_delta_to_message_chunk(
        {"role": "custom_role", "content": "c"}, ChatMessageChunk
    )
    assert isinstance(chunk, ChatMessageChunk)
    assert chunk.role == "custom_role"


# ---------------------------------------------------------------------------
# _convert_delta_to_message_chunk — function_call
# ---------------------------------------------------------------------------


def test_delta_with_function_call() -> None:
    delta: Dict[str, Any] = {
        "role": "assistant",
        "content": "",
        "function_call": {"name": "my_tool", "arguments": {"a": 1}},
    }
    chunk = _convert_delta_to_message_chunk(delta, AIMessageChunk)
    assert isinstance(chunk, AIMessageChunk)
    assert chunk.additional_kwargs["function_call"]["name"] == "my_tool"
    assert len(chunk.tool_call_chunks) == 1
    assert chunk.tool_call_chunks[0]["name"] == "my_tool"
    args = chunk.tool_call_chunks[0]["args"]
    assert args is not None
    assert json.loads(args) == {"a": 1}


def test_delta_function_call_name_none() -> None:
    delta: Dict[str, Any] = {
        "role": "assistant",
        "content": "",
        "function_call": {"name": None, "arguments": {}},
    }
    chunk = _convert_delta_to_message_chunk(delta, AIMessageChunk)
    assert chunk.additional_kwargs["function_call"]["name"] == ""


# ---------------------------------------------------------------------------
# _convert_delta_to_message_chunk — functions_state_id
# ---------------------------------------------------------------------------


def test_delta_functions_state_id() -> None:
    delta: Dict[str, Any] = {
        "content": "text",
        "functions_state_id": "sid-1",
    }
    chunk = _convert_delta_to_message_chunk(delta, AIMessageChunk)
    assert isinstance(chunk, AIMessageChunk)
    assert chunk.additional_kwargs["functions_state_id"] == "sid-1"


# ---------------------------------------------------------------------------
# _convert_delta_to_message_chunk — reasoning_content
# ---------------------------------------------------------------------------


def test_delta_reasoning_content() -> None:
    delta: Dict[str, Any] = {
        "role": "assistant",
        "content": "answer",
        "reasoning_content": "thinking...",
    }
    chunk = _convert_delta_to_message_chunk(delta, AIMessageChunk)
    assert chunk.additional_kwargs["reasoning_content"] == "thinking..."


# ---------------------------------------------------------------------------
# _convert_delta_to_message_chunk — image regex in content
# ---------------------------------------------------------------------------


def test_delta_image_regex() -> None:
    content = '<img src="uuid-img" fuse="true"/>text after'
    delta: Dict[str, Any] = {"role": "assistant", "content": content}
    chunk = _convert_delta_to_message_chunk(delta, AIMessageChunk)
    assert chunk.additional_kwargs["image_uuid"] == "uuid-img"
    assert chunk.additional_kwargs["postfix_message"] == "text after"


def test_delta_video_regex() -> None:
    content = '<video cover="cover-1" src="video-1" fuse="true"/>after'
    delta: Dict[str, Any] = {"role": "assistant", "content": content}
    chunk = _convert_delta_to_message_chunk(delta, AIMessageChunk)
    assert chunk.additional_kwargs["cover_uuid"] == "cover-1"
    assert chunk.additional_kwargs["video_uuid"] == "video-1"


# ---------------------------------------------------------------------------
# _build_stream_chunk
# ---------------------------------------------------------------------------


@pytest.fixture()
def gigachat_instance(mocker: MockerFixture) -> GigaChat:
    mocker.patch("gigachat.GigaChat")
    return GigaChat()


def test_build_stream_chunk_first_chunk(gigachat_instance: GigaChat) -> None:
    raw_chunk: Dict[str, Any] = {
        "choices": [{"delta": {"role": "assistant", "content": "hi"}, "index": 0}],
        "created": 123,
        "model": "GigaChat:v1",
        "object": "chat.completion",
        "x_headers": {"x-request-id": "req-1"},
    }
    chunk_m, gen_info, content = gigachat_instance._build_stream_chunk(
        raw_chunk, first_chunk=True
    )
    assert isinstance(chunk_m, AIMessageChunk)
    assert chunk_m.id == "req-1"
    assert gen_info["x_headers"] == {"x-request-id": "req-1"}


def test_build_stream_chunk_not_first_chunk(gigachat_instance: GigaChat) -> None:
    raw_chunk: Dict[str, Any] = {
        "choices": [{"delta": {"role": "assistant", "content": "more"}, "index": 0}],
        "created": 123,
        "model": "GigaChat:v1",
        "object": "chat.completion",
    }
    _, gen_info, _ = gigachat_instance._build_stream_chunk(raw_chunk, first_chunk=False)
    assert "x_headers" not in gen_info


def test_build_stream_chunk_with_finish_reason(gigachat_instance: GigaChat) -> None:
    raw_chunk: Dict[str, Any] = {
        "choices": [
            {
                "delta": {"role": "assistant", "content": "done"},
                "index": 0,
                "finish_reason": "stop",
            }
        ],
        "created": 123,
        "model": "GigaChat:v1",
        "object": "chat.completion",
    }
    _, gen_info, _ = gigachat_instance._build_stream_chunk(raw_chunk, first_chunk=False)
    assert gen_info["finish_reason"] == "stop"
    assert gen_info["model_name"] == "GigaChat:v1"


def test_build_stream_chunk_with_usage(gigachat_instance: GigaChat) -> None:
    raw_chunk: Dict[str, Any] = {
        "choices": [{"delta": {"role": "assistant", "content": ""}, "index": 0}],
        "created": 123,
        "model": "GigaChat:v1",
        "object": "chat.completion",
        "usage": {
            "prompt_tokens": 10,
            "completion_tokens": 20,
            "total_tokens": 30,
            "precached_prompt_tokens": 5,
        },
    }
    chunk_m, _, _ = gigachat_instance._build_stream_chunk(raw_chunk, first_chunk=False)
    assert isinstance(chunk_m, AIMessageChunk)
    assert chunk_m.usage_metadata is not None
    assert chunk_m.usage_metadata["input_tokens"] == 15
    assert chunk_m.usage_metadata["output_tokens"] == 20
    assert chunk_m.usage_metadata["total_tokens"] == 35


def test_build_stream_chunk_without_content_uses_empty_string(
    gigachat_instance: GigaChat,
) -> None:
    raw_chunk: Dict[str, Any] = {
        "choices": [
            {
                "delta": {
                    "role": "assistant",
                    "function_call": {"name": "my_tool", "arguments": {}},
                },
                "index": 0,
            }
        ],
        "created": 123,
        "model": "GigaChat:v1",
        "object": "chat.completion",
    }
    _, _, content = gigachat_instance._build_stream_chunk(raw_chunk, first_chunk=True)
    assert content == ""


class _TokenRecorder(BaseCallbackHandler):
    def __init__(self) -> None:
        self.tokens: list[str] = []

    def on_llm_new_token(self, token: str, **kwargs: Any) -> None:
        self.tokens.append(token)


@pytest.mark.parametrize("asynchronous", [False, True])
@pytest.mark.parametrize(
    "ending", ["finish", "eof", "metadata_only", "after_finish", "cleared"]
)
async def test_legacy_public_stream_uses_latest_metadata_snapshots(
    mocker: MockerFixture, asynchronous: bool, ending: str
) -> None:
    """Response snapshots must not concatenate during public chunk aggregation."""
    initial = {
        "thread_id": "thread-1",
        "message_id": "message-1",
        "additional_data": {
            "sources": [{"index": 0, "url": "https://example.com", "title": "Draft"}],
            "obsolete": True,
        },
        "error_details": {"http_status": 102, "message": "Pending"},
    }
    final = {
        "thread_id": "thread-1",
        "message_id": "message-1",
        "additional_data": {
            "sources": [{"index": 0, "url": "https://example.com", "title": "Final"}]
        },
        "error_details": {"http_status": 200, "message": "Complete"},
    }
    if ending == "cleared":
        final.update(additional_data={}, error_details={})
    usage = {
        "prompt_tokens": 5,
        "precached_prompt_tokens": 2,
        "completion_tokens": 3,
        "total_tokens": 8,
    }
    raw_chunks: list[dict[str, Any]] = [
        {
            "choices": [{"delta": {"content": "Hello "}}],
            "x_headers": {"x-request-id": "request-1"},
            **initial,
        },
        {"choices": [{"delta": {"content": "world"}}], **initial},
    ]
    if ending == "eof":
        raw_chunks[-1].update(final, usage=usage)
    elif ending in ("metadata_only", "after_finish", "cleared"):
        if ending == "after_finish":
            raw_chunks[-1]["choices"][0]["finish_reason"] = "stop"
        raw_chunks.append({"choices": [], "usage": usage, **final})
    else:
        raw_chunks.append(
            {
                "choices": [{"delta": {}, "finish_reason": "stop"}],
                "usage": usage,
                **final,
            }
        )
    for raw_chunk in raw_chunks:
        raw_chunk["model"] = "test-model"
    consumed = 0

    def stream(*args: Any) -> Iterator[dict[str, Any]]:
        nonlocal consumed
        for raw_chunk in raw_chunks:
            consumed += 1
            yield raw_chunk

    async def astream(*args: Any) -> AsyncIterator[dict[str, Any]]:
        for raw_chunk in stream():
            yield raw_chunk

    sdk_client = mocker.patch("gigachat.GigaChat").return_value
    sdk_client.stream.side_effect = stream
    sdk_client.astream.side_effect = astream
    recorder = _TokenRecorder()
    llm = GigaChat(model="test-model", callbacks=[recorder])
    if asynchronous:
        async_iterator = llm.astream("hello")
        first = await anext(async_iterator)
        assert consumed == 1, "Text must be yielded before the SDK stream ends"
        chunks = [first, *[chunk async for chunk in async_iterator]]
    else:
        iterator = llm.stream("hello")
        first = next(iterator)
        assert consumed == 1, "Text must be yielded before the SDK stream ends"
        chunks = [first, *iterator]

    assert first.content == "Hello "
    assert all(
        not (chunk.response_metadata.keys() & final.keys()) for chunk in chunks[:-1]
    )
    assert chunks[-1].response_metadata == final
    assert chunks[-1].id == "request-1"
    assert chunks[-1].chunk_position == "last"
    aggregate = chunks[0]
    for chunk in chunks[1:]:
        aggregate += chunk
    assert aggregate.content == "Hello world"
    assert aggregate.id == "request-1"
    assert all(
        aggregate.response_metadata[key] == value for key, value in final.items()
    )
    assert aggregate.response_metadata["x_headers"] == {"x-request-id": "request-1"}
    assert aggregate.usage_metadata == {
        "input_tokens": 7,
        "output_tokens": 3,
        "total_tokens": 10,
        "input_token_details": {"cache_read": 2},
    }
    assert "".join(recorder.tokens) == "Hello world"

    # LangChain's invoke-with-streaming path must preserve the same snapshots.
    recorder.tokens.clear()
    response = (
        await llm.ainvoke("hello", stream=True)
        if asynchronous
        else llm.invoke("hello", stream=True)
    )
    assert response.content == aggregate.content
    assert response.id == aggregate.id
    assert response.usage_metadata == aggregate.usage_metadata
    assert response.response_metadata == aggregate.response_metadata
    assert "".join(recorder.tokens) == "Hello world"

"""Reusable SDK-shaped fixtures for the primary chat contract tests."""

from __future__ import annotations

from typing import Optional

import gigachat.models as gm

MODEL = "GigaChat-3-Ultra"
CREATED_AT = 1_754_000_000
REQUEST_ID = "request-primary-001"
SESSION_ID = "session-primary-001"
THREAD_ID = "thread-primary-001"
MESSAGE_ID = "message-primary-001"
TOOLS_STATE_ID = "tools-state-primary-001"


def build_official_sdk_server_tool_stream() -> list[gm.PrimaryChatCompletionChunk]:
    """Return the exact named-event payloads stable SDK v0.2.3 tests parse."""
    payloads = [
        {
            "event": "response.message.delta",
            "model": "GigaChat",
            "created_at": "167890456789",
            "messages": [{"role": "assistant", "content": "primary chunk"}],
        },
        {
            "event": "response.tool.completed",
            "model": "GigaChat",
            "created_at": "167890456790",
            "messages": [
                {
                    "role": "reasoning",
                    "content": [
                        {
                            "tool_execution": {
