                },
                "output_tokens": 2,
                "total_tokens": 3,
            },
        },
    ]
    return [
        gm.PrimaryChatCompletionChunk.model_validate(payload) for payload in payloads
    ]


def _x_headers() -> dict[str, Optional[str]]:
    return {
        "x-request-id": REQUEST_ID,
        "x-session-id": SESSION_ID,
    }


def _usage() -> gm.ChatUsage:
    return gm.ChatUsage(
