def test_terminal_usage_and_transport_metadata_contract_parity() -> None:
    usage = {
        "input_tokens": 8,
        "input_tokens_details": {"prompt_tokens": 8, "cached_tokens": 3},
        "output_tokens": 5,
        "total_tokens": 13,
    }
    metadata = {
        "message_id": "message-1",
