        True,
        gm.ChatStorage(thread_id="thread-1"),
        {"thread_id": "thread-1"},
    ],
)
def test_primary_storage_accepts_only_primary_sdk_forms(storage: Any) -> None:
    payload = primary.build_payload(
        [],
